import{_ as t,o as s,c as i,ah as a}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Direction","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/direction/index.md","filePath":"src/guide/direction/index.md"}'),r={name:"guide/direction/index.md"};function n(o,e,d,l,u,c){return s(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="direction" tabindex="-1">Direction <a class="header-anchor" href="#direction" aria-label="Permalink to &quot;Direction&quot;">​</a></h1><p>Deux profils sont prévus pour celles et ceux qui dirigent l&#39;établissement sans en faire la saisie au quotidien :</p><ul><li>la <strong>direction de site</strong> — le directeur ou la directrice d&#39;un campus. Elle est rattachée à un ou plusieurs sites et décide de ce qui les concerne ;</li><li>la <strong>direction générale</strong> — le chef d&#39;établissement ou le promoteur. Elle voit tous les sites et peut décider de tout.</li></ul><p>Ces profils font partie du module <strong>Pilotage</strong>. C&#39;est l&#39;administrateur qui les attribue, depuis <a href="/era-guide/guide/admin/personnel-utilisateurs.html">Personnel et comptes utilisateurs</a>.</p><div class="info custom-block"><p class="custom-block-title">Ce que la direction ne voit pas</p><p>Une direction n&#39;a pas accès aux écrans opérationnels : caisse, notes, dossiers de candidature, réglages. Elle voit les demandes qui attendent sa décision, regroupées dans <a href="/era-guide/guide/direction/a-approuver.html">À approuver</a>, et la page <a href="/era-guide/guide/direction/pilotage.html">Pilotage</a> avec les indicateurs de ses sites.</p></div><h2 id="votre-espace" tabindex="-1">Votre espace <a class="header-anchor" href="#votre-espace" aria-label="Permalink to &quot;Votre espace&quot;">​</a></h2><p>À la connexion, le <strong>Tableau de bord</strong> liste ce qui attend votre décision, avec le nombre de demandes en attente. L&#39;espace <strong>Direction</strong> du menu s&#39;ouvre sur <a href="/era-guide/guide/direction/a-approuver.html">À approuver</a>, qui rassemble sur une seule page tout ce que vous pouvez décider, puis la page <strong>Pilotage</strong> et les trois files complètes :</p><ul><li><strong>Mobilité inter-site</strong> — les transferts d&#39;élèves entre deux sites ;</li><li><strong>Mutations de personnel</strong> — les changements de site d&#39;un employé ;</li><li><strong>Dépenses</strong> — les demandes de dépense des sites.</li></ul><p>Une direction de site n&#39;y voit que les demandes qui touchent <strong>ses</strong> sites. La direction générale voit tout.</p><h2 id="qui-decide-de-quoi" tabindex="-1">Qui décide de quoi <a class="header-anchor" href="#qui-decide-de-quoi" aria-label="Permalink to &quot;Qui décide de quoi&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Demande</th><th>Direction de site</th><th>Direction générale</th></tr></thead><tbody><tr><td>Mobilité d&#39;un élève</td><td>valide la part de son site (départ ou arrivée)</td><td>peut valider les deux</td></tr><tr><td>Mutation d&#39;un membre du personnel</td><td>décide si l&#39;un des deux sites est le sien</td><td>décide</td></tr><tr><td>Dépense</td><td>décide jusqu&#39;au <strong>seuil</strong> fixé par l&#39;établissement, inclus</td><td>décide, sans limite</td></tr></tbody></table><p>L&#39;administrateur garde toujours la main sur tout.</p><p>Un site <strong>sans direction</strong> fonctionne comme avant : le secrétariat y valide sa part des mobilités, et l&#39;administration décide des mutations et des dépenses. Il en va de même si le compte de la direction est désactivé.</p><h2 id="mobilites-d-eleves" tabindex="-1">Mobilités d&#39;élèves <a class="header-anchor" href="#mobilites-d-eleves" aria-label="Permalink to &quot;Mobilités d&#39;élèves&quot;">​</a></h2><p>Une mobilité doit être validée par le site de départ <strong>et</strong> par le site d&#39;arrivée. Ouvrez la demande avec <strong>Examiner</strong> :</p><ul><li>le bloc de votre site propose <strong>Approuver l&#39;origine</strong> ou <strong>Approuver la destination</strong> ; pour l&#39;arrivée, choisissez la classe d&#39;accueil ;</li><li>le bloc de l&#39;autre site indique <strong>En attente de la validation de ce site</strong> tant qu&#39;il n&#39;a pas répondu.</li></ul><p>Le transfert s&#39;exécute dès que les deux parts sont validées, dans n&#39;importe quel ordre. Vous pouvez aussi <strong>Refuser</strong> la demande, avec un motif.</p><h2 id="mutations-de-personnel" tabindex="-1">Mutations de personnel <a class="header-anchor" href="#mutations-de-personnel" aria-label="Permalink to &quot;Mutations de personnel&quot;">​</a></h2><p>Une seule décision suffit : <strong>Approuver</strong> applique le changement de site, <strong>Refuser</strong> demande un motif. Les directions des deux sites sont prévenues ; la première qui décide clôt la demande.</p><h2 id="depenses" tabindex="-1">Dépenses <a class="header-anchor" href="#depenses" aria-label="Permalink to &quot;Dépenses&quot;">​</a></h2><p>Ouvrez une dépense pour voir son montant, sa description et son justificatif, puis <strong>Approuver</strong> ou <strong>Refuser</strong>.</p><p>Au-delà du seuil, la fiche l&#39;indique — <em>Montant au-delà du seuil de validation de la direction de site</em> — et la décision revient à la direction générale ou à un administrateur. Vous n&#39;êtes alors pas notifié de ces dépenses, mais vous les voyez dans la liste de vos sites.</p><p>L&#39;administrateur fixe ce seuil dans <a href="/era-guide/guide/admin/parametres-application.html#approbations">Paramètres de l&#39;application → Approbations</a>.</p><h2 id="classes-en-sureffectif" tabindex="-1">Classes en sureffectif <a class="header-anchor" href="#classes-en-sureffectif" aria-label="Permalink to &quot;Classes en sureffectif&quot;">​</a></h2><p>Quand une classe de votre site reçoit un élève alors qu&#39;elle est pleine, vous recevez une notification <em>Classe en sureffectif</em> : qui a forcé l&#39;affectation, l&#39;effectif atteint et le <strong>motif</strong> saisi. Il n&#39;y a rien à valider : c&#39;est une information, pour que ces dépassements ne passent plus inaperçus.</p><h2 id="recevoir-les-demandes-sur-votre-telephone" tabindex="-1">Recevoir les demandes sur votre téléphone <a class="header-anchor" href="#recevoir-les-demandes-sur-votre-telephone" aria-label="Permalink to &quot;Recevoir les demandes sur votre téléphone&quot;">​</a></h2><p>Dans <strong>Paramètres → Notifications</strong>, activez les notifications sur votre téléphone. Chaque nouvelle demande arrive alors en notification ; un appui ouvre la page <a href="/era-guide/guide/direction/a-approuver.html">À approuver</a>, avec la demande mise en avant.</p>',27)])])}const g=t(r,[["render",n]]);export{m as __pageData,g as default};
